{
  "PROP-6a4369e9-inv-011": {
    "property_id": "PROP-6a4369e9-inv-011",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-011",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::verify_data_column_sidecar::L538-540",
      "proof_trace": "The empty kzg_commitments check at L538-540 is enforced only in gossip and block publishing paths. RPC-received data columns bypass verify_data_column_sidecar entirely, going directly to KZG verification in data_availability_checker.rs:446, which accepts empty commitment lists.",
      "attack_scenario": "Attacker sends DataColumnSidecar with empty kzg_commitments via RPC DataColumnsByRange/DataColumnsByRoot request. Bypasses structural validation, passes KZG batch verification (empty list valid), and gets imported into availability cache with semantically invalid state.",
      "checklist_id": "PROP-6a4369e9-inv-011"
    },
    "text": "kzg_commitments must not be empty in a valid data column sidecar.",
    "assertion": "forall sidecar: accepted(sidecar) => len(sidecar.kzg_commitments) > 0",
    "covers": "SG-002",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

